import {CHURTON_VIEWS} from './churton-ward.mjs';
import {NEW_HOSPITAL_GROUND_VIEW} from './new-hospital.mjs';
import * as THREE from './vendor/three.module.js';
import {createEscapeExterior,loadEscapeFrontage} from './escape-exterior.mjs';
import {FRONT_STEPS_VIEW} from './front-steps.mjs';
import {FRONT_WALL_VIEW} from './front-boundary-wall.mjs';
import {REDESMERE_PASSAGE_VIEW} from './redesmere-passage.mjs';
import {createWalker,exteriorObstacles} from './explore-controls.mjs';
import {EAST_PHOTO_VIEW} from './east-photo-detail.mjs';
import {COURTYARD_PHOTO_VIEW} from './courtyard-photo-detail.mjs';
import {REAR_COURT_PHOTO_VIEW} from './rear-court-photo-detail.mjs';
import {WEST_FRONT_PHOTO_VIEW} from './west-front-photo-detail.mjs';
import {WEST_COURT_PHOTO_VIEW} from './west-court-photo-detail.mjs';
import {centralCourtPhotoView} from './central-court-photo-detail.mjs';
import {innerEastPhotoView} from './inner-east-elevation.mjs';
import {WEST_WING_SIDE_VIEW,WEST_WING_END_VIEW} from './west-wing-photo-detail.mjs';
import {INNER_COURT_PHOTO_VIEW} from './inner-court-photo-detail.mjs';
import {REDESMERE_PHOTO_VIEW} from './redesmere-photo-detail.mjs';
import {EAST_LAWN_PHOTO_VIEW,ENTRANCE_EAST_PHOTO_VIEW} from './entrance-symmetry.mjs';
import {WEST_FORWARD_END_PHOTO_VIEW} from './west-forward-end-photo-detail.mjs';
import {WEST_LAWN_PHOTO_VIEW} from './west-lawn-photo-detail.mjs';
import {ENTRANCE_WEST_PHOTO_VIEW} from './entrance-west-photo-detail.mjs';
const canvas=document.getElementById('game'),hint=document.getElementById('lookHint'),look=document.getElementById('look');
try{
  const renderer=new THREE.WebGLRenderer({canvas,antialias:true});
  renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);
  renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;
  renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
  const exterior=createEscapeExterior(THREE,innerWidth/innerHeight);
  exterior.camera.near=.1;exterior.camera.updateProjectionMatrix();
  const walker=createWalker(exterior.camera,exteriorObstacles(THREE,exterior.model));
  if(new URLSearchParams(location.search).get('view')==='redesmere-passage')walker.setView(REDESMERE_PASSAGE_VIEW);
  if(new URLSearchParams(location.search).get('view')==='east-photo')walker.setView(EAST_PHOTO_VIEW);
  if(new URLSearchParams(location.search).get('view')==='courtyard-photo')walker.setView(COURTYARD_PHOTO_VIEW);
  if(new URLSearchParams(location.search).get('view')==='west-front-photo')walker.setView(WEST_FRONT_PHOTO_VIEW);
  if(new URLSearchParams(location.search).get('view')==='west-court-photo')walker.setView(WEST_COURT_PHOTO_VIEW);
  if(new URLSearchParams(location.search).get('view')==='inner-court-photo')walker.setView(INNER_COURT_PHOTO_VIEW);
  if(new URLSearchParams(location.search).get('view')==='rear-court-photo')walker.setView(REAR_COURT_PHOTO_VIEW);
  if(new URLSearchParams(location.search).get('view')==='inner-east-photo')walker.setView(innerEastPhotoView(exterior.camera.aspect));
  if(new URLSearchParams(location.search).get('view')==='central-court-photo')walker.setView(centralCourtPhotoView(exterior.camera.aspect));
  if(new URLSearchParams(location.search).get('view')==='west-wing-side')walker.setView(WEST_WING_SIDE_VIEW);
  if(new URLSearchParams(location.search).get('view')==='west-wing-end')walker.setView(WEST_WING_END_VIEW);
  if(new URLSearchParams(location.search).get('view')==='redesmere-photo')walker.setView(REDESMERE_PHOTO_VIEW);
  if(new URLSearchParams(location.search).get('view')==='entrance-west-photo')walker.setView(ENTRANCE_WEST_PHOTO_VIEW);
  if(new URLSearchParams(location.search).get('view')==='west-lawn-photo')walker.setView(WEST_LAWN_PHOTO_VIEW);
  if(new URLSearchParams(location.search).get('view')==='east-lawn-photo')walker.setView(EAST_LAWN_PHOTO_VIEW);
  if(new URLSearchParams(location.search).get('view')==='entrance-east-photo')walker.setView(ENTRANCE_EAST_PHOTO_VIEW);
  if(new URLSearchParams(location.search).get('view')==='west-forward-end-photo')walker.setView(WEST_FORWARD_END_PHOTO_VIEW);
  if(new URLSearchParams(location.search).get('view')==='front-steps')walker.setView({...FRONT_STEPS_VIEW,position:[6,1.8,34]});
  if(new URLSearchParams(location.search).get('view')==='front-wall')walker.setView({...FRONT_WALL_VIEW,position:[0,1.8,36],target:[-12,.8,49]});
  if(new URLSearchParams(location.search).get('view')==='new-hospital')walker.setView(NEW_HOSPITAL_GROUND_VIEW);
  const churtonView=new URLSearchParams(location.search).get('view');
  if(CHURTON_VIEWS[churtonView])walker.setView(CHURTON_VIEWS[churtonView==='churton'||churtonView==='churton-plan'?'churton-4':churtonView]);
  let active=false,dragging=false,last=null;
  const movement=new Set(['KeyW','KeyA','KeyS','KeyD','ShiftLeft','ShiftRight']);
  function stop(){active=false;dragging=false;last=null;walker.keys.clear();hint.textContent='Click Start exploring to resume, or drag the view to look around.';look.textContent='START EXPLORING ↗';}
  function begin(){active=true;canvas.focus();hint.textContent='Walk with WASD. If the cursor stays visible, hold and drag to look around.';}
  function lock(){begin();try{canvas.requestPointerLock?.()?.catch(()=>{hint.textContent='Mouse capture is unavailable here. Hold and drag the view to look around; WASD moves.';});}catch{hint.textContent='Hold and drag the view to look around; WASD moves.';}}
  look.disabled=false;hint.textContent='Click Start exploring for mouse look, or hold and drag the view.';look.onclick=lock;
  document.getElementById('resetView').onclick=()=>{walker.reset();begin();};
  canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;begin();dragging=true;last={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});
  canvas.addEventListener('pointerup',()=>{dragging=false;last=null;});
  canvas.addEventListener('pointercancel',()=>{dragging=false;last=null;walker.keys.clear();});
  canvas.addEventListener('pointermove',e=>{if(document.pointerLockElement===canvas||!dragging)return;if(last)walker.look(e.clientX-last.x,e.clientY-last.y);last={x:e.clientX,y:e.clientY};});
  document.addEventListener('mousemove',e=>{if(active&&document.pointerLockElement===canvas)walker.look(e.movementX,e.movementY);});
  document.addEventListener('pointerlockchange',()=>{const locked=document.pointerLockElement===canvas;document.body.classList.toggle('mouse-locked',locked);if(locked)begin();else stop();});
  document.addEventListener('keydown',e=>{if(e.code==='Escape'){stop();document.exitPointerLock?.();return;}if(active&&movement.has(e.code)){e.preventDefault();walker.keys.add(e.code);}});
  document.addEventListener('keyup',e=>walker.keys.delete(e.code));
  window.addEventListener('blur',stop);
  document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
  window.addEventListener('resize',()=>{renderer.setSize(innerWidth,innerHeight);exterior.camera.aspect=innerWidth/innerHeight;if(new URLSearchParams(location.search).get('view')==='inner-east-photo')exterior.camera.fov=innerEastPhotoView(exterior.camera.aspect).fov;if(new URLSearchParams(location.search).get('view')==='central-court-photo')exterior.camera.fov=centralCourtPhotoView(exterior.camera.aspect).fov;exterior.camera.updateProjectionMatrix();});
  const clock=new THREE.Clock();
  renderer.setAnimationLoop(()=>{const dt=clock.getDelta();if(active&&!document.hidden)walker.update(dt);renderer.render(exterior.scene,exterior.camera);});
  loadEscapeFrontage(THREE,exterior).catch(error=>console.warn('Frontage photo unavailable',error));
}catch(error){console.error(error);hint.textContent='The grounds could not load. Reload the page to try again.';look.disabled=false;look.textContent='RELOAD ↗';look.onclick=()=>location.reload();}
